const tradeIcon='<svg viewBox="0 0 56 56" aria-hidden="true"><defs><linearGradient id="trade-blue" x2="0" y2="1"><stop stop-color="#08bfff"/><stop offset="1" stop-color="#0752b7"/></linearGradient></defs><circle cx="28" cy="28" r="26" fill="url(#trade-blue)" stroke="#064886" stroke-width="2"/><path d="M28 9 44 18 28 27 12 18Zm-16 13 16 9 16-9v6l-16 9-16-9Zm0 10 16 9 16-9v6l-16 9-16-9Z" fill="white"/><path d="M28 27v22" stroke="#078bd8" stroke-width="1.5"/></svg>';
function tradeResults(){return tradeProducts.filter(p=>(!tradeState.keyword||(p.name+' '+p.provider).toLowerCase().includes(tradeState.keyword.toLowerCase()))&&tradeGroups.every(([key])=>tradeState[key]==='全部'||tradeState[key]==='全域'||p[key]===tradeState[key]))}
function tradeCards(){const items=tradeResults();return items.length?items.map(p=>`<button class="trade-card" data-trade-product="${p.id}" ${req('portal.trade.products','trade.product.'+p.id)}><h2>${p.name}</h2><div class="trade-card-banner"><span class="trade-product-icon">${tradeIcon}</span><span class="trade-badges"><span>已上架</span><span>${p.industry}</span></span></div><div class="trade-card-body"><p class="trade-description">${p.name}</p><strong class="trade-price">¥${p.price.toFixed(2)}</strong><dl><div><dt>数据提供方</dt><dd>${p.provider}</dd></div><div><dt>更新频率</dt><dd>1 ${p.frequency}</dd></div><div><dt>数据主体</dt><dd>${p.subject}</dd></div><div><dt>上架时间</dt><dd>${p.time}</dd></div></dl></div></button>`).join(''):`<div class="trade-empty"><span>⌕</span><h2>暂无符合条件的数据产品</h2><p>请调整关键词或筛选条件后重试</p><button class="btn primary" data-trade-reset ${req('portal.trade.query','trade.reset')}>重置筛选</button></div>`}
function trade(){home();const header=app.querySelector('.topbar').outerHTML;app.innerHTML=`<main class="trade-page" data-req-page="portal-trade" data-req-surface="portal.trade" data-req-title="门户数据交易"><div>${header}</div><div class="trade-content"><div class="trade-heading"><h1><span>▣</span> 数据产品</h1><p>浏览并发现优质数据产品</p></div><section class="trade-filters" aria-label="数据产品查询与筛选" ${req('portal.trade.query')}><form id="trade-search" class="trade-search"><input id="trade-keyword" aria-label="产品关键词" maxlength="100" placeholder="输入关键字查询" value="${safeText(tradeState.draft)}" ${req('portal.trade.query','trade.keyword')}><button type="submit" ${req('portal.trade.query','trade.search')}>查询</button></form><div class="trade-filter-groups">${tradeGroups.map(([key,label,options])=>`<div class="trade-filter-row"><span class="trade-filter-label">${label}:</span><div class="trade-options" role="group" aria-label="${label}">${options.map(value=>`<button type="button" class="trade-chip ${tradeState[key]===value?'selected':''}" aria-pressed="${tradeState[key]===value}" data-trade-filter="${key}" data-trade-value="${value}" ${req('portal.trade.query','trade.filter.'+key)}>${value}</button>`).join('')}</div></div>`).join('')}</div></section><section class="trade-grid" aria-label="数据产品列表" aria-live="polite" ${req('portal.trade.products')}>${tradeCards()}</section><div class="trade-count">共 <span id="trade-total">${tradeResults().length}</span> 个数据产品</div></div></main>`;app.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.action==='trade'));}
function refreshTradeResults(){app.querySelector('.trade-grid').innerHTML=tradeCards();$('#trade-total').textContent=tradeResults().length}
document.addEventListener('input',e=>{if(e.target.id==='trade-keyword')tradeState.draft=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id!=='trade-search')return;e.preventDefault();tradeState.keyword=tradeState.draft.trim();refreshTradeResults()});
document.addEventListener('click',e=>{const filter=e.target.closest('[data-trade-filter]');if(filter){tradeState[filter.dataset.tradeFilter]=filter.dataset.tradeValue;filter.closest('.trade-options').querySelectorAll('button').forEach(b=>{const active=b===filter;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});refreshTradeResults();return}if(e.target.closest('[data-trade-reset]')){Object.assign(tradeState,{keyword:'',draft:'',type:'全部',industry:'全部',delivery:'全部',subject:'全部',frequency:'全部',region:'本区域'});trade();return}const card=e.target.closest('[data-trade-product]');if(card){const p=tradeProducts.find(p=>p.id===card.dataset.tradeProduct);show(`<section class="dialog trade-detail" role="dialog" aria-modal="true" aria-labelledby="trade-detail-title" data-req-page="portal-trade" data-req-surface="portal.trade.detail" ${req('portal.trade.products','trade.detail')}><div class="dialog-head"><h2 id="trade-detail-title">产品详情</h2><button class="close" data-action="close" aria-label="关闭产品详情">×</button></div><div class="dialog-body"><h2>${p.name}</h2><p class="trade-price">¥${p.price.toFixed(2)}</p><div class="info-grid">${[['数据提供方',p.provider],['产品类型',p.type],['行业类型',p.industry],['交付方式',p.delivery],['数据主体',p.subject],['更新频率','1 '+p.frequency],['区域类型',p.region],['上架时间',p.time]].map(([k,v])=>info(k,v)).join('')}</div><p class="hint">当前为产品展示原型，价格及商品信息用于页面演示。</p></div><footer class="dialog-footer"><button class="btn primary" data-action="close">返回列表</button></footer></section>`);root.querySelector('.close').focus()}});


