function resourceResults(){return resourceData.filter(r=>(resourceState.industry==='全部'||r.industry===resourceState.industry)&&(resourceState.region==='全域'||r.region===resourceState.region)&&(!resourceState.keyword||(r.name+' '+r.code+' '+r.owner).toLowerCase().includes(resourceState.keyword.toLowerCase())))}
function resourceMetadata(r){return [['资源标识码',r.code],['资源持有方',r.owner],['联系人',r.contact],['联系方式',r.phone],['创建时间',r.time]]}
function resourceCards(){const rows=resourceResults();return rows.length?rows.map(r=>`<article class="trade-card resource-card" ${req('portal.resources.list','resource.card.'+r.id)}><h2>${r.name}</h2><div class="trade-card-banner"><span class="trade-product-icon">${tradeIcon}</span><span class="trade-badges"><span class="resource-approved">已通过</span><span>${r.industry}</span></span></div><div class="trade-card-body"><dl>${resourceMetadata(r).map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><button class="resource-details" data-resource-detail="${r.id}" ${req('portal.resources.list','resource.detail.'+r.id)} aria-label="查看${r.name}详情">▧ 详情</button></div></article>`).join(''):`<div class="trade-empty"><span>⌕</span><h2>暂无符合条件的数据资源</h2><p>请调整关键词或筛选条件后重试</p><button class="btn primary" data-resource-reset ${req('portal.resources.query','resource.reset')}>重置筛选</button></div>`}
function resources(){home();const header=app.querySelector('.topbar').outerHTML;app.innerHTML=`<main class="trade-page resource-page" data-req-page="portal-resources" data-req-surface="portal.resources" data-req-title="门户数据资源"><div>${header}</div><div class="trade-content"><div class="trade-heading"><h1><span>▥</span> 数据资源</h1><p>管理和检索各类数据资源信息</p></div><section class="trade-filters" aria-label="数据资源查询与筛选" ${req('portal.resources.query')}><form class="trade-search" id="resource-search"><input id="resource-keyword" aria-label="资源关键词" placeholder="输入关键字查询" maxlength="100" value="${safeText(resourceState.draft)}" ${req('portal.resources.query','resource.keyword')}><button type="submit" ${req('portal.resources.query','resource.search')}>查询</button></form><div class="trade-filter-groups">${tradeGroups.filter(([k])=>['industry','region'].includes(k)).map(([key,label,options])=>`<div class="trade-filter-row"><span class="trade-filter-label">${key==='industry'?'行业分类':label}:</span><div class="trade-options" role="group" aria-label="${key==='industry'?'行业分类':label}">${options.map(value=>`<button type="button" class="trade-chip ${resourceState[key]===value?'selected':''}" aria-pressed="${resourceState[key]===value}" data-resource-filter="${key}" data-resource-value="${value}" ${req('portal.resources.query','resource.filter.'+key)}>${value}</button>`).join('')}</div></div>`).join('')}</div></section><section class="trade-grid" aria-label="数据资源列表" aria-live="polite" ${req('portal.resources.list')}>${resourceCards()}</section><div class="trade-count">共 <span id="resource-total">${resourceResults().length}</span> 个数据资源</div></div></main>`;}
function refreshResources(){app.querySelector('.trade-grid').innerHTML=resourceCards();$('#resource-total').textContent=resourceResults().length}
document.addEventListener('input',e=>{if(e.target.id==='resource-keyword')resourceState.draft=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id!=='resource-search')return;e.preventDefault();resourceState.keyword=resourceState.draft.trim();refreshResources()});
document.addEventListener('click',e=>{const f=e.target.closest('[data-resource-filter]');if(f){resourceState[f.dataset.resourceFilter]=f.dataset.resourceValue;f.closest('.trade-options').querySelectorAll('button').forEach(btn=>{btn.classList.toggle('selected',btn===f);btn.setAttribute('aria-pressed',String(btn===f))});refreshResources();return}if(e.target.closest('[data-resource-reset]')){Object.assign(resourceState,{keyword:'',draft:'',industry:'全部',region:'本区域'});resources();return}const d=e.target.closest('[data-resource-detail]');if(d){const r=resourceData.find(x=>x.id===d.dataset.resourceDetail);show(`<section class="dialog trade-detail" role="dialog" aria-modal="true" aria-labelledby="resource-detail-title" data-req-page="portal-resources" data-req-surface="portal.resources.detail" ${req('portal.resources.list','resource.detail')}><div class="dialog-head"><h2 id="resource-detail-title">数据资源详情</h2><button class="close" data-action="close" aria-label="关闭资源详情">×</button></div><div class="dialog-body"><h2>${r.name}</h2><span class="pill">已通过</span><div class="info-grid">${[...resourceMetadata(r),['行业分类',r.industry],['区域类型',r.region]].map(([k,v])=>info(k,v)).join('')}</div></div><footer class="dialog-footer"><button class="btn primary" data-action="close">返回列表</button></footer></section>`);root.querySelector('.close').focus()}});
